/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        ne(members.status, "invited"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Counts owners who can still act as workspace owners. */
export async function countActiveOwners(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(and(
      orgPredicate(members.orgId, orgId),
      eq(members.role, "owner"),
      eq(members.status, "active"),
      liveMemberPredicate(),
    ))
    .get();
  return row?.value ?? 0;
}

