export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const member = requireFound(await memberRepo.findMemberById(input.orgId, input.memberId), "Member", input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  if (member.userId === actor.userId) throw new Error("You cannot suspend yourself");
  if (member.status === "suspended") return member;
  assertTargetRole(actor, member);
  if (member.role === "owner" && (await memberRepo.countActiveOwners(input.orgId)) <= 1) {
    throw new Error("An organization must keep at least one active owner");
  }
  const suspended = await memberRepo.updateMemberStatus(input.orgId, input.memberId, "suspended");
  await emit("member.suspended", { ...actorEnvelope(actor), memberId: suspended.id, userId: suspended.userId });
  return suspended;
}

export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const member = requireFound(await memberRepo.findMemberById(input.orgId, input.memberId), "Member", input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  if (member.status !== "suspended") return member;
  if (member.userId === actor.userId) throw new Error("You cannot reinstate yourself");
  assertTargetRole(actor, member);
  const reinstated = await memberRepo.updateMemberStatus(input.orgId, input.memberId, "active");
  await emit("member.reinstated", { ...actorEnvelope(actor), memberId: reinstated.id, userId: reinstated.userId });
  return reinstated;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

